head.script:
scwin.vScrenID = "ULDBNS25100";
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.param2 = "";

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {

};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.img_CoSearch_onclick = async function (e) {
    const url = "/ui/bns/bnslistsrchl/ULDBNS25001.xml";
    const popTitle = "발행기관명검색";

    const opts = {
        id: "ULDBNS25001",
        popupName: popTitle,
        width: 900,
        height: 679,
        frameModal: "top",
    };
    const data = {};
    scwin.param1 = txb_ISUR_CD.getValue();
    scwin.param2 = txb_COM_NM.getValue();

    const rtn = await  $c.win.openPopup(url, opts, data);

    txb_ISUR_CD.setValue(rtn.isurCd);
    txb_COM_NM.setValue(rtn.isurNm);
};
